slides.codeSnippet:
// Component
counter = 0;
increment() {
  this.counter++;
}

// Template
<button (click)="increment()">Click me!</button>
<p>Count: {{ counter }}</p>

// Component
inputValue = '';
onInput(event: any) {
  this.inputValue = event.target.value;
}

// Template
<input (input)="onInput($event)" [value]="inputValue">
<p>You typed: {{ inputValue }}</p>
